# Convert expression to three-address code
def to_three_address(expr):
    temps = []
    counter = [0]

    def new_temp():
        counter[0] += 1
        return f't{counter[0]}'

    def emit(op, left, right):
        dest = new_temp()
        temps.append(f'{dest} = {left} {op} {right}')
        return dest

    def convert(e):
        if isinstance(e, Number):
            return str(e.value)
        if isinstance(e, BinOp):
            l = convert(e.left)
            r = convert(e.right)
            return emit(e.op, l, r)

    final = convert(expr)
    return temps, final

# Example: a + b * c
# Output: ['t1 = b * c', 't2 = a + t1'], result in t2
